fn parse_url_char(mut s: state, ch: c_char) -> state { unsafe {
    let chi = ch as c_int;
    let chu = ch as c_uchar as c_uint;

    if chi == ' ' as i32 || chi == '\r' as i32 || chi == '\n' as i32 || chi == '\t' as i32 || chi == '\u{c}' as i32 {
        return s_dead;
    }

    let lower = ((chi | 0x20) as c_uchar) as c_int;
    let is_alpha = lower >= 'a' as i32 && lower <= 'z' as i32;
    let is_normal = (normal_url_char[(chu >> 3) as usize] as c_uint & ((1 as c_uint) << (chu & 7))) != 0;

    match s as c_uint {
        20 => {
            if chi == '/' as i32 || chi == '*' as i32 {
                return s_req_path;
            }
            if is_alpha {
                return s_req_schema;
            }
            s_dead
        }
        21 => {
            if is_alpha {
                return s;
            }
            if chi == ':' as i32 {
                return s_req_schema_slash;
            }
            s_dead
        }
        22 => {
            if chi == '/' as i32 {
                return s_req_schema_slash_slash;
            }
            s_dead
        }
        23 => {
            if chi == '/' as i32 {
                return s_req_server_start;
            }
            s_dead
        }
        24 | 25 => {
            if chi == '/' as i32 {
                return s_req_path;
            }
            if chi == '?' as i32 {
                return s_req_query_string_start;
            }
            if chi == '@' as i32 {
                return s_req_server_with_at;
            }
            if is_alpha
                || (chi >= '0' as i32 && chi <= '9' as i32)
                || chi == '-' as i32
                || chi == '_' as i32
                || chi == '.' as i32
                || chi == '!' as i32
                || chi == '~' as i32
                || chi == '*' as i32
                || chi == '\'' as i32
                || chi == '(' as i32
                || chi == ')' as i32
                || chi == '%' as i32
                || chi == ';' as i32
                || chi == ':' as i32
                || chi == '&' as i32
                || chi == '=' as i32
                || chi == '+' as i32
                || chi == '$' as i32
                || chi == ',' as i32
                || chi == '[' as i32
                || chi == ']' as i32
            {
                return s_req_server;
            }
            s_dead
        }
        26 => {
            if chi == '@' as i32 {
                return s_dead;
            }
            if chi == '/' as i32 {
                return s_req_path;
            }
            if chi == '?' as i32 {
                return s_req_query_string_start;
            }
            if chi == '@' as i32 {
                return s_req_server_with_at;
            }
            if is_alpha
                || (chi >= '0' as i32 && chi <= '9' as i32)
                || chi == '-' as i32
                || chi == '_' as i32
                || chi == '.' as i32
                || chi == '!' as i32
                || chi == '~' as i32
                || chi == '*' as i32
                || chi == '\'' as i32
                || chi == '(' as i32
                || chi == ')' as i32
                || chi == '%' as i32
                || chi == ';' as i32
                || chi == ':' as i32
                || chi == '&' as i32
                || chi == '=' as i32
                || chi == '+' as i32
                || chi == '$' as i32
                || chi == ',' as i32
                || chi == '[' as i32
                || chi == ']' as i32
            {
                return s_req_server;
            }
            s_dead
        }
        27 => {
            if is_normal {
                return s;
            }
            if chi == '?' as i32 {
                return s_req_query_string_start;
            }
            if chi == '#' as i32 {
                return s_req_fragment_start;
            }
            s_dead
        }
        28 | 29 => {
            if is_normal || chi == '?' as i32 {
                return s_req_query_string;
            }
            if chi == '#' as i32 {
                return s_req_fragment_start;
            }
            s_dead
        }
        30 => {
            if is_normal || chi == '?' as i32 {
                return s_req_fragment;
            }
            if chi == '#' as i32 {
                return s;
            }
            s_dead
        }
        31 => {
            if is_normal || chi == '?' as i32 || chi == '#' as i32 {
                return s;
            }
            s_dead
        }
        _ => s_dead,
    }
} }

